import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`on-call responder: declare a new incident with a severity level, title, and description`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a responder submits a new incident with severity, title, and description, every team member sees it appear on the dashboard within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0: open the create form and submit a new incident
      await pageA.getByTestId('action-create_incident').click();
      await pageA.getByTestId('field-title').fill('DB connection pool exhausted');
      await pageA.getByTestId('field-description').fill('Primary DB read replicas returning timeouts since 14:32 UTC');
      await pageA.getByTestId('field-severity').fill('critical');
      await pageA.getByTestId('action-create_incident').click();

      // Node 1: the incident should appear on the dashboard within 5s
      await expect(
        pageB.getByTestId('item-incident').filter({ hasText: 'DB connection pool exhausted' })
      ).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`the incident is created with status 'open' and the declarer recorded as its creator`, async ({ page }) => {
    // Open the create form and submit
    await page.getByTestId('action-create_incident').click();
    await page.getByTestId('field-title').fill('Status check incident');
    await page.getByTestId('field-description').fill('Verifying open status on creation');
    await page.getByTestId('field-severity').fill('high');
    await page.getByTestId('action-create_incident').click();

    // The incident item should appear and carry status 'open'
    const item = page.getByTestId('item-incident').filter({ hasText: 'Status check incident' });
    await expect(item).toBeVisible({ timeout: 5_000 });
    await expect(item).toContainText('open');
  });
});
